/**
 * Bounded language enumeration and CYK membership.
 *
 * IMPORTANT: comparing the sets of strings up to a length bound is evidence,
 * not a proof, of language equivalence. (Equivalence of context-free grammars
 * is undecidable in general.)
 */
import { nonTerminalSet } from '../algorithms/grammar.js';

const SEP = '\u0001';

/**
 * Enumerate all terminal strings of length ≤ maxLength generated by `grammar`.
 * Works for ANY context-free grammar (ε-rules, unit rules, cycles…): it
 * computes, for each variable, the set of words of length ≤ maxLength it
 * derives, by a monotone fixed-point iteration over finite sets.
 * Strings are returned as arrays joined with a separator-free key form.
 *
 * @returns {Set<string>} words encoded as symbols joined by U+0001 ('' = ε)
 */
export function enumerateLanguage(grammar, maxLength, { maxWords = 200000 } = {}) {
  const nts = nonTerminalSet(grammar);
  const lang = new Map(grammar.nonTerminals.map((n) => [n, new Map()])); // word key -> length
  const termWord = (t) => new Map([[t, 1]]);

  const concat = (a, b) => {
    const out = new Map();
    for (const [wa, la] of a) {
      for (const [wb, lb] of b) {
        const len = la + lb;
        if (len > maxLength) continue;
        const key = wa === '' ? wb : wb === '' ? wa : wa + SEP + wb;
        out.set(key, len);
      }
    }
    return out;
  };

  let changed = true;
  let guard = 0;
  while (changed) {
    changed = false;
    guard += 1;
    if (guard > 10000) throw new Error('Language enumeration did not converge.');
    for (const p of grammar.productions) {
      let acc = new Map([['', 0]]);
      for (const s of p.rhs) {
        const part = nts.has(s) ? lang.get(s) ?? new Map() : termWord(s);
        acc = concat(acc, part);
        if (acc.size === 0) break;
      }
      const target = lang.get(p.lhs);
      for (const [w, l] of acc) {
        if (!target.has(w)) {
          target.set(w, l);
          changed = true;
          if (target.size > maxWords) throw new Error('Too many strings to enumerate; lower the length bound.');
        }
      }
    }
  }
  return new Set(lang.get(grammar.start)?.keys() ?? []);
}

export function decodeWord(key) {
  return key === '' ? [] : key.split(SEP);
}

export function wordToString(key) {
  const symbols = decodeWord(key);
  if (symbols.length === 0) return 'ε';
  return symbols.join(symbols.some((s) => [...s].length > 1) ? ' ' : '');
}

/**
 * Compare two grammars on all strings up to `maxLength`.
 * @returns {{ equal, onlyInFirst: string[], onlyInSecond: string[], count, maxLength }}
 */
export function compareLanguages(g1, g2, maxLength) {
  const a = enumerateLanguage(g1, maxLength);
  const b = enumerateLanguage(g2, maxLength);
  const onlyInFirst = [...a].filter((w) => !b.has(w));
  const onlyInSecond = [...b].filter((w) => !a.has(w));
  const sortWords = (list) =>
    list.sort((x, y) => decodeWord(x).length - decodeWord(y).length || x.localeCompare(y));
  return {
    equal: onlyInFirst.length === 0 && onlyInSecond.length === 0,
    onlyInFirst: sortWords(onlyInFirst).map(wordToString),
    onlyInSecond: sortWords(onlyInSecond).map(wordToString),
    words: sortWords([...a]).map(wordToString),
    count: a.size,
    maxLength,
  };
}

/**
 * Tokenise an input string into terminal symbols of `grammar`, using the
 * longest terminal match (so multi-character terminals work). Whitespace is
 * ignored. Returns { ok, tokens, error }.
 */
export function tokenizeInput(input, grammar) {
  const terminals = [...grammar.terminals].sort((x, y) => y.length - x.length);
  const tokens = [];
  let i = 0;
  const text = input.trim();
  if (text === '' || text === 'ε' || text === 'epsilon') return { ok: true, tokens: [] };
  while (i < text.length) {
    if (/\s/.test(text[i])) {
      i += 1;
      continue;
    }
    const match = terminals.find((t) => text.startsWith(t, i));
    if (!match) {
      return { ok: false, tokens, error: `"${text[i]}" at position ${i + 1} is not a terminal of this grammar.` };
    }
    tokens.push(match);
    i += match.length;
  }
  return { ok: true, tokens };
}

/**
 * CYK membership test for a grammar in CNF.
 * table[len-1][i] = set of variables deriving tokens[i .. i+len-1]
 * @returns {{ accepted, table, tokens }}
 */
export function cyk(grammar, tokens) {
  const n = tokens.length;
  if (n === 0) {
    const accepted = grammar.productions.some((p) => p.lhs === grammar.start && p.rhs.length === 0);
    return { accepted, table: [], tokens };
  }
  const terminalRules = grammar.productions.filter((p) => p.rhs.length === 1);
  const binaryRules = grammar.productions.filter((p) => p.rhs.length === 2);
  const table = Array.from({ length: n }, (_, len) => Array.from({ length: n - len }, () => new Set()));
  tokens.forEach((t, i) => {
    for (const p of terminalRules) if (p.rhs[0] === t) table[0][i].add(p.lhs);
  });
  for (let len = 2; len <= n; len += 1) {
    for (let i = 0; i + len <= n; i += 1) {
      const cell = table[len - 1][i];
      for (let split = 1; split < len; split += 1) {
        const left = table[split - 1][i];
        const right = table[len - split - 1][i + split];
        if (!left.size || !right.size) continue;
        for (const p of binaryRules) {
          if (left.has(p.rhs[0]) && right.has(p.rhs[1])) cell.add(p.lhs);
        }
      }
    }
  }
  return {
    accepted: table[n - 1][0].has(grammar.start),
    table: table.map((row) => row.map((cell) => [...cell])),
    tokens,
  };
}
